"""Score observed MCP tool calls against scenario expected-tools ground truth.

Each YAML ``expected_tools`` entry is scored independently. Two entry shapes
exist:

- **Standalone** ``tool_called`` — one expected tool that must appear somewhere
  in the conversation (presence only).
- **``tool_group``** — multiple expected tools that must co-occur on one user
  turn; optional ``ordered: true`` enforces call order within that turn.

An observed tool call satisfies an expected tool when the name is equal, the
call did not error, and every argument named in the expected spec equals the
observed value (strict ``==`` equality, matching ``slot_was_set`` assertions).
When arguments
are omitted in YAML, any observed args are accepted.

Per-entry metrics — ``tool_group`` entries are scored against one turn;
standalone ``tool_called`` entries against the full conversation:

**precision** (diagnostic only — does not gate pass/fail):

Answers: "How many of the observed tool calls were expected?"

- ``tool_group``:
  ``matched_observed_tool_calls_on_turn / observed_tool_calls_on_turn``
- Standalone ``tool_called``:
  ``matched_observed_tool_calls_in_conversation /
  observed_tool_calls_in_conversation``

**recall** (diagnostic only — does not gate pass/fail):

Answers: "How many of the expected tools were found?"

- ``tool_group``:
  ``matched_expected_tools_on_turn / expected_tools_in_group``
  (also used to pick the best turn for reports when no turn is perfect,
  i.e. tools are spread across turns)
- Standalone ``tool_called``:
  ``1.0`` if the expected tool was matched by at least one observed tool call,
  else ``0.0``

**accuracy** (binary — gates pass/fail when ``gate: true``):

Answers: "Did this entry match perfectly?"

- ``1.0`` if the entry matched perfectly, else ``0.0``.
- ``tool_group``: ``1.0`` when every expected tool in the group was matched on
  one turn (correct arguments, correct order when ``ordered: true``), and
  there are no unmatched observed tool calls on that turn.
- Standalone ``tool_called``: ``1.0`` when the expected tool was matched by at
  least one observed tool call; unmatched observed tool calls elsewhere do not
  reduce accuracy.

Conversation-level scores are the arithmetic mean of each metric across all
``expected_tools`` entries (``None`` values excluded). Only per-entry accuracy
on gated entries affects scenario pass/fail.
"""

from __future__ import annotations

from pydantic import BaseModel, ConfigDict, Field

from rasa.builder.copilot.mcp_server.tools.expected_tools import (
    ExpectedTool,
    ExpectedToolGroup,
)
from rasa.builder.copilot.mcp_server.tools.observed_tools import (
    ObservedTool,
    ToolRunEvent,
    events_on_turn,
    turn_indices,
)

SCORE_METRICS = (
    "precision",
    "recall",
    "accuracy",
)  # Metric names averaged for the conversation-level mean.

__all__ = (
    "SCORE_METRICS",
    "ToolScoringResult",
    "ToolScoresPerEntry",
    "ToolScoresPerConversation",
    "score_tools",
)


class ToolScoringResult(BaseModel):
    """Precision, recall, and accuracy for one expected-vs-observed comparison."""

    precision: float | None = None  # Diagnostic only; not used for pass/fail.
    recall: float | None = None  # Diagnostic only; matched specs / total expected.
    accuracy: float | None = None  # ``1.0`` only on a perfect entry match.
    failure_reason: str | None = (
        None  # First scoring failure detail; None when the entry matched perfectly
    )


class ToolScoresPerEntry(ToolScoringResult):
    """Per-entry ``expected_tools`` score plus gate metadata for the run report."""

    matched_turn_index: int | None = (
        None  # Turn where this entry first matched; report-only, not used in scoring
    )
    gate: bool = False
    assertion_label: str = ""
    gate_passed: bool = True  # ``accuracy == 1.0`` when ``gate`` is set on the entry.


class ToolScoresPerConversation(ToolScoringResult):
    """Conversation mean metrics and one score row per expected_tools entry."""

    per_entry: list[ToolScoresPerEntry] = Field(default_factory=list)


from rasa.builder.copilot.mcp_server.tools.tool_formatting import (  # noqa: E402
    format_assertion_label,
    format_tool,
)


def _accuracy_passed(accuracy: float | None) -> bool:
    """Return whether a scored expected_tools entry passed (accuracy is 1.0)."""
    return accuracy is not None and accuracy > 0.0


def _tool_identifies_as(expected_tool: ExpectedTool, observed: ToolRunEvent) -> bool:
    """Return whether name/args align, ignoring dispatch error state."""
    observed_name = (observed.tool_name or "").strip()
    if observed_name != expected_tool.tool_name:
        return False
    if expected_tool.arguments is None:
        return True
    actual = dict(observed.arguments or {})
    return all(
        actual.get(name) == expected_value
        for name, expected_value in expected_tool.arguments.items()
    )


def _tool_matches(expected_tool: ExpectedTool, observed: ToolRunEvent) -> bool:
    """Return whether an observed MCP tool call satisfies an expected tool.

    Errored calls never match, even when name/args align — gated scenarios
    must not pass on a failed dispatch. Argument values use strict ``==``
    equality (same as ``slot_was_set`` assertions).
    """
    if observed.is_error:
        return False
    return _tool_identifies_as(expected_tool, observed)


def _dispatch_failure_reason(
    expected_tool: ExpectedTool,
    observed: ToolRunEvent,
    *,
    location: str,
) -> str:
    """Build a failure reason when the right tool was called but dispatch errored."""
    return (
        f"{location}expected {format_tool(expected_tool)}, "
        f"dispatch failed ({format_tool(observed)})"
    )


def _missing_tool_failure_reason(
    expected_tool: ExpectedTool,
    observed_tools: list[ToolRunEvent],
    *,
    exclude_indices: set[int],
    location: str,
) -> str:
    """Distinguish absent tools from errored dispatches that matched name/args."""
    for observed_index, observed in enumerate(observed_tools):
        if observed_index in exclude_indices:
            continue
        if _tool_identifies_as(expected_tool, observed) and observed.is_error:
            return _dispatch_failure_reason(expected_tool, observed, location=location)
    return (
        f"{location}expected {format_tool(expected_tool)} "
        "not found among observed tools"
    )


def _build_turn_scoring_result(
    *,
    expected_tools: list[ExpectedTool],
    observed_tools: list[ToolRunEvent],
    matched_indices: set[int],
    perfect_match: bool,
    failure_reason: str | None,
) -> ToolScoringResult:
    """Derive precision/recall/accuracy from a turn-level match scan."""
    matched_tools_on_turn = len(matched_indices)
    # Vacuous match: nothing expected and nothing observed on this turn.
    if not expected_tools and not observed_tools:
        return ToolScoringResult(precision=1.0, recall=1.0, accuracy=1.0)

    # Precision scope is one turn (used by ``tool_group`` scoring).
    if not expected_tools:
        precision = None  # No expected specs → precision is not applicable.
    elif not observed_tools:
        precision = 0.0  # Expected tools on this turn but none observed.
    else:
        # Matched observed tools on this turn / all observed tools on this turn.
        precision = matched_tools_on_turn / len(observed_tools)

    # Recall: how many expected tools in the group were satisfied on this turn.
    recall = None if not expected_tools else matched_tools_on_turn / len(expected_tools)
    # Accuracy: binary pass bit — requires every expected tool, correct order when
    # ``ordered: true``, specified args, and no extra calls on the turn.
    if not expected_tools:
        accuracy = None
    elif perfect_match:
        accuracy = 1.0
    else:
        accuracy = 0.0
    return ToolScoringResult(
        precision=precision,
        recall=recall,
        accuracy=accuracy,
        failure_reason=failure_reason,
    )


class _OrderedToolCallScan(BaseModel):
    """Result of scanning one expected tool call in an ordered turn group."""

    model_config = ConfigDict(frozen=True)

    matched_observed_index: int | None = None
    failure_reason: str | None = None


def _match_ordered_tool_call(
    expected_tools: list[ExpectedTool],
    tool_index: int,
    expected_tool: ExpectedTool,
    observed_tools: list[ToolRunEvent],
    *,
    cursor: int,
    scope_label: str,
) -> _OrderedToolCallScan:
    """Find the next observed call for one ordered expected tool."""
    for observed_index in range(cursor, len(observed_tools)):
        observed = observed_tools[observed_index]
        if _tool_identifies_as(expected_tool, observed) and observed.is_error:
            # Skip failed dispatches so a later successful retry can satisfy order.
            continue
        if _tool_matches(expected_tool, observed):
            return _OrderedToolCallScan(matched_observed_index=observed_index)
        if any(
            _tool_matches(later, observed) for later in expected_tools[tool_index + 1 :]
        ):
            return _OrderedToolCallScan(
                failure_reason=(
                    f"{scope_label} tool {tool_index + 1}: expected "
                    f"{format_tool(expected_tool)}, got "
                    f"{format_tool(observed)} out of order"
                )
            )

    return _OrderedToolCallScan(
        failure_reason=_missing_tool_failure_reason(
            expected_tool,
            observed_tools,
            exclude_indices=set(range(cursor)),
            location=f"{scope_label} tool {tool_index + 1}: ",
        )
    )


def _collect_between_extras(
    observed_tools: list[ToolRunEvent],
    *,
    cursor: int,
    match_index: int,
    expected_tool: ExpectedTool,
) -> list[ToolRunEvent]:
    """Return surplus observed calls between an ordered match cursor and match."""
    return [
        observed
        for observed in observed_tools[cursor:match_index]
        if not (observed.is_error and _tool_identifies_as(expected_tool, observed))
    ]


def _failure_for_surplus_ordered_calls(
    *,
    scope_label: str,
    extra_calls: list[ToolRunEvent],
    had_between_extras: bool,
) -> str:
    """Build a failure reason when ordered tools matched but extra calls remain."""
    placement = (
        "between expected tools" if had_between_extras else "after expected sequence"
    )
    return (
        f"{scope_label}: extra observed tool "
        f"{format_tool(extra_calls[0])} {placement}"
    )


def _score_ordered_on_turn(
    expected_tools: list[ExpectedTool],
    observed_tools: list[ToolRunEvent],
    *,
    scope_label: str,
) -> ToolScoringResult:
    """Score an ordered tool group against observed tools on one turn."""
    matched_indices: set[int] = set()
    failure_reason: str | None = None
    perfect_match = True  # Flipped to False on miss, out-of-order, or extra calls.
    cursor = 0
    extra_calls: list[ToolRunEvent] = []  # Unmatched calls break accuracy.
    had_between_extras = False

    for tool_index, expected_tool in enumerate(expected_tools):
        scan = _match_ordered_tool_call(
            expected_tools,
            tool_index,
            expected_tool,
            observed_tools,
            cursor=cursor,
            scope_label=scope_label,
        )
        if scan.failure_reason is not None:
            failure_reason = scan.failure_reason
            perfect_match = False
            break

        match_index = scan.matched_observed_index
        if match_index is None:
            perfect_match = False
            break

        if match_index > cursor:
            between_extras = _collect_between_extras(
                observed_tools,
                cursor=cursor,
                match_index=match_index,
                expected_tool=expected_tool,
            )
            if between_extras:
                had_between_extras = True
                extra_calls.extend(between_extras)
        matched_indices.add(match_index)
        cursor = match_index + 1

    if failure_reason is None and cursor < len(observed_tools):
        extra_calls.extend(observed_tools[cursor:])

    if (
        failure_reason is None
        and len(matched_indices) == len(expected_tools)
        and extra_calls
    ):
        failure_reason = _failure_for_surplus_ordered_calls(
            scope_label=scope_label,
            extra_calls=extra_calls,
            had_between_extras=had_between_extras,
        )
        perfect_match = False

    return _build_turn_scoring_result(
        expected_tools=expected_tools,
        observed_tools=observed_tools,
        matched_indices=matched_indices,
        perfect_match=perfect_match,
        failure_reason=failure_reason,
    )


def _score_unordered_on_turn(
    expected_tools: list[ExpectedTool],
    observed_tools: list[ToolRunEvent],
    *,
    scope_label: str,
) -> ToolScoringResult:
    """Score an unordered tool group against observed tools on one turn."""
    matched_indices: set[int] = set()
    failure_reason: str | None = None
    perfect_match = True  # Flipped to False on miss or extra calls on the turn.

    for tool_index, expected_tool in enumerate(expected_tools):
        match_index = next(
            (
                observed_index
                for observed_index, observed in enumerate(observed_tools)
                if observed_index not in matched_indices
                and _tool_matches(expected_tool, observed)
            ),
            None,
        )
        if match_index is None:
            failure_reason = _missing_tool_failure_reason(
                expected_tool,
                observed_tools,
                exclude_indices=matched_indices,
                location=f"{scope_label} tool {tool_index + 1}: ",
            )
            perfect_match = False
            break
        matched_indices.add(match_index)

    if failure_reason is None:
        extras = [
            observed
            for index, observed in enumerate(observed_tools)
            if index not in matched_indices
            and not (
                observed.is_error
                and any(
                    _tool_identifies_as(expected_tool, observed)
                    for expected_tool in expected_tools
                )
            )
        ]
        if extras:
            # Expected set fully matched, but additional calls exist, so accuracy 0.0.
            failure_reason = (
                f"{scope_label}: extra observed tool "
                f"{format_tool(extras[0])} beyond expected set"
            )
            perfect_match = False

    return _build_turn_scoring_result(
        expected_tools=expected_tools,
        observed_tools=observed_tools,
        matched_indices=matched_indices,
        perfect_match=perfect_match,
        failure_reason=failure_reason,
    )


def _score_tool_group(
    entry: ExpectedToolGroup,
    observed_tools: list[ObservedTool],
) -> tuple[ToolScoringResult, int | None]:
    """Score one ``tool_group`` entry and return its best-matching turn.

    Each user turn is scored independently; the first perfect turn wins.
    When no turn is perfect, keep the turn with highest recall for diagnostics.
    """
    score_on_turn = (
        _score_ordered_on_turn if entry.ordered else _score_unordered_on_turn
    )
    best: tuple[ToolScoringResult, int | None] | None = None
    for turn_index in turn_indices(observed_tools):
        score = score_on_turn(
            entry.tools,
            events_on_turn(turn_index, observed_tools),
            scope_label=f"T{turn_index}",
        )
        if _accuracy_passed(score.accuracy):
            return score, turn_index  # First turn with a perfect group match wins.
        # No perfect turn: keep the turn with highest recall for diagnostics.
        if best is None or (score.recall or 0) > (best[0].recall or 0):
            best = score, turn_index
    if best is not None:
        return best
    # No observed tool calls at all in the conversation.
    return ToolScoringResult(recall=0.0, accuracy=0.0), None


def _score_standalone_tool(
    entry: ExpectedTool,
    observed_tools: list[ObservedTool],
) -> tuple[ToolScoringResult, int | None]:
    """Score one standalone ``tool_called`` entry.

    Standalone entries are presence-only: the tool must appear somewhere in the
    conversation. Extra MCP calls elsewhere reduce precision (diagnostic) but
    do not reduce accuracy.
    """
    # Standalone entries only require presence somewhere in the conversation.
    matching_turns = [
        tool.turn_index for tool in observed_tools if _tool_matches(entry, tool.event)
    ]
    total_calls = len(observed_tools)
    if matching_turns:
        # Precision spans the whole conversation (diagnostic, not gating).
        precision = len(matching_turns) / total_calls if total_calls else 0.0
        return (
            # Presence-only: recall/accuracy 1.0; extras elsewhere do not fail.
            ToolScoringResult(precision=precision, recall=1.0, accuracy=1.0),
            matching_turns[0],
        )

    errored_matches = [
        tool
        for tool in observed_tools
        if _tool_identifies_as(entry, tool.event) and tool.event.is_error
    ]
    if errored_matches:
        return (
            ToolScoringResult(
                precision=0.0 if total_calls else None,
                recall=0.0,
                accuracy=0.0,
                failure_reason=_dispatch_failure_reason(
                    entry,
                    errored_matches[0].event,
                    location="any turn: ",
                ),
            ),
            None,
        )

    return (
        ToolScoringResult(
            precision=0.0 if total_calls else None,  # Calls seen, but none matched.
            recall=0.0,  # Expected tool never found.
            accuracy=0.0,  # Missing expected tool → gated entries fail.
            failure_reason=f"any turn: expected {format_tool(entry)} not found",
        ),
        None,
    )


def _aggregate_per_entry(per_entry: list[ToolScoresPerEntry]) -> ToolScoringResult:
    """Average per-entry metrics into conversation-level scores.

    ``failure_reason`` comes from the first gated or ungated entry that failed;
    conversation-level precision/recall/accuracy are unweighted means.
    """
    # Entries with ``None`` for a metric are excluded from that metric's mean.
    metric_values = {
        metric: [
            value
            for entry in per_entry
            if (value := getattr(entry, metric)) is not None
        ]
        for metric in SCORE_METRICS
    }
    # Arithmetic mean across ``expected_tools`` entries (report "Conversation mean").
    aggregated = {
        metric: (
            sum(values) / len(values) if (values := metric_values[metric]) else None
        )
        for metric in SCORE_METRICS
    }
    return ToolScoringResult(
        precision=aggregated["precision"],
        recall=aggregated["recall"],
        accuracy=aggregated["accuracy"],
        failure_reason=next(
            (entry.failure_reason for entry in per_entry if entry.failure_reason),
            None,
        ),
    )


def score_tools(
    observed_tools: list[ObservedTool],
    expected_tools: list[ExpectedTool | ExpectedToolGroup],
) -> ToolScoresPerConversation | None:
    """Score observed MCP tool calls against scenario ``expected_tools``.

    Returns:
        Conversation-level metrics and per-entry scores, or ``None`` when
        ``expected_tools`` is empty.
    """
    if not expected_tools:
        return None

    per_entry: list[ToolScoresPerEntry] = []
    for expected_entry in expected_tools:
        if isinstance(expected_entry, ExpectedToolGroup):
            score, matched_turn_index = _score_tool_group(
                expected_entry, observed_tools
            )
        else:
            score, matched_turn_index = _score_standalone_tool(
                expected_entry, observed_tools
            )

        gate = expected_entry.gate
        per_entry.append(
            ToolScoresPerEntry(
                matched_turn_index=matched_turn_index,
                gate=gate,
                assertion_label=format_assertion_label(expected_entry),
                # Gated entries must achieve perfect accuracy; others are informational.
                gate_passed=_accuracy_passed(score.accuracy) if gate else True,
                **score.model_dump(),
            )
        )

    return ToolScoresPerConversation(
        **_aggregate_per_entry(per_entry).model_dump(),
        per_entry=per_entry,
    )
